"""Flask app exposing keyset (/rank) and naive OFFSET (/rank_offset) ranking pages."""
import math

from flask import Flask, jsonify, request

from db import init

app = Flask(__name__)
_conn = None


def conn():
    global _conn
    if _conn is None:
        _conn = init()
    return _conn


PAGE_DEFAULT = 50
MAX_LIMIT = 500


def _params():
    category = request.args.get("category", "cat0")
    try:
        limit = int(request.args.get("limit", PAGE_DEFAULT))
    except ValueError:
        limit = PAGE_DEFAULT
    limit = max(1, min(limit, MAX_LIMIT))
    return category, limit


@app.get("/rank")
def rank_keyset():
    """Keyset (seek) pagination on (score DESC, id ASC) with id as tiebreak."""
    category, limit = _params()

    where = ["category = ?"]
    args = [category]

    after_score = request.args.get("after_score")
    after_id = request.args.get("after_id")
    if after_score is not None and after_id is not None:
        try:
            s = float(after_score)
            i = int(after_id)
        except ValueError:
            return jsonify(error="invalid after_score/after_id"), 400
        # Next page starts strictly after the last row of the previous page
        # in (score DESC, id ASC) order.
        where.append("(score < ? OR (score = ? AND id > ?))")
        args.extend([s, s, i])
    elif after_score is not None or after_id is not None:
        return jsonify(error="after_score and after_id must be given together"), 400

    sql = (
        "SELECT id, category, score FROM ranks "
        f"WHERE {' AND '.join(where)} "
        "ORDER BY score DESC, id ASC LIMIT ?"
    )
    rows = conn().execute(sql, [*args, limit]).fetchall()
    items = [{"id": r[0], "category": r[1], "score": r[2]} for r in rows]
    next_cursor = None
    if len(rows) == limit:
        last = rows[-1]
        next_cursor = {"after_score": last[2], "after_id": last[0]}
    return jsonify(items=items, next_cursor=next_cursor)


@app.get("/rank_offset")
def rank_offset():
    """Naive LIMIT/OFFSET pagination over the same total ordering."""
    category, limit = _params()
    try:
        offset = int(request.args.get("offset", 0))
    except ValueError:
        return jsonify(error="invalid offset"), 400
    offset = max(0, offset)

    rows = conn().execute(
        "SELECT id, category, score FROM ranks "
        "WHERE category = ? ORDER BY score DESC, id ASC LIMIT ? OFFSET ?",
        [category, limit, offset],
    ).fetchall()
    items = [{"id": r[0], "category": r[1], "score": r[2]} for r in rows]
    return jsonify(items=items)


if __name__ == "__main__":
    app.run(debug=False, port=5000)

